// ------------------------------------------------------------------ spirits: made of light, fog and ash, they always glow
static void face(Cr *c, float x, float y, float s, int sad){ cr_eye(c, x - s * 0.9f, y, s * 0.75f); cr_eye(c, x + s * 0.9f, y, s * 0.75f); if(sad) cv_curve(&c->cv, x - s * 0.7f, y + s * 2.3f, x, y + s * 1.6f, x + s * 0.7f, y + s * 2.3f, 0.3f, 0.3f, &c->dk, SH_FLAT); else cv_curve(&c->cv, x - s * 0.7f, y + s * 1.7f, x, y + s * 2.5f, x + s * 0.7f, y + s * 1.7f, 0.3f, 0.3f, &c->dk, SH_FLAT); }
static void notes(Cr *c, float x, float y, int n){ for(int i = 0; i < n; i++){ float xx = x + i * 5, yy = y - i * 4 + (i & 1) * 3; cv_dot(&c->cv, xx, yy + 3, 1.3f, c->bn.c[3], 1); cv_flat(&c->cv, xx + 1.2f, yy + 3, xx + 1.2f, yy - 2, 0.35f, c->bn.c[3], 1); cv_flat(&c->cv, xx + 1.2f, yy - 2, xx + 3.2f, yy - 1, 0.35f, c->bn.c[3], 1); } }
